INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'ja-JP', 'name', 'プライバシーポリシー', 'reviewed', SHA2('隐私协议', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'ja-JP', 'value', '<h2>プライバシーポリシー</h2><p>本アプリをご利用いただきありがとうございます。アカウントへのログイン、アプリ機能、カスタマーサービスの提供に必要な範囲でのみ、お客様の個人情報を取り扱い、保護します。</p><h3>一、情報の利用</h3><p>法令および本ポリシーに従ってお客様の情報を利用し、関係のない目的には利用しません。</p><h3>二、お客様の権利</h3><p>法令に基づき、個人情報の照会、訂正、削除を請求できます。また、アプリに掲載された窓口からお問い合わせいただけます。</p>', 'reviewed', SHA2('<h2>隐私政策</h2><p>感谢您使用本应用。我们重视并保护您的个人信息，仅在提供账号登录、应用功能和客户服务所必需的范围内处理相关信息。</p><h3>一、信息使用</h3><p>我们会按照法律法规和本协议约定使用您的信息，不会将其用于无关目的。</p><h3>二、您的权利</h3><p>您可以依法查询、更正、删除个人信息，或通过应用内公布的渠道联系我们。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'ja-JP', 'name', 'サービス利用規約', 'reviewed', SHA2('服务条款', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'ja-JP', 'value', '<h2>サービス利用規約</h2><p>本アプリへようこそ。本アプリをご利用になる前に、本規約をご確認ください。アプリサービスの利用を開始した時点で、本規約および関連ルールに同意したものとみなされます。</p><h3>一、サービスの利用</h3><p>各機能は、画面の案内に従い、法令を遵守してご利用ください。本アプリを違法行為や他者の権利を侵害する行為に利用してはなりません。</p><h3>二、規約の変更</h3><p>事業や法令の変更に応じて本規約を更新する場合があります。更新後の内容はアプリ内に表示します。</p>', 'reviewed', SHA2('<h2>服务条款</h2><p>欢迎使用本应用。使用本应用前，请您阅读并理解本协议。您开始使用应用服务，即表示同意遵守本协议及相关规则。</p><h3>一、服务使用</h3><p>请您依法、合规并按照页面提示使用各项功能，不得利用本应用从事违法或损害他人权益的活动。</p><h3>二、协议变更</h3><p>我们会根据业务和法律法规变化更新本协议，并在应用内向您展示更新后的内容。</p>', 256), NULL, NULL, 1, '2026-08-03 16:49:48', 1, 1, '2026-08-03 16:49:48', '2026-08-03 16:49:48', 0);
